package dev.zomboidmelee.boxing;import dev.kosmx.playerAnim.minecraftApi.PlayerAnimationAccess;import de.maxhenkel.corpse.entities.DummyPlayer;
public class CorpseChecks38 {public static void main(String[]a){if(CorpseAnimation38.block(new Object()))throw new AssertionError("live entity changed");for(String id:new String[]{"lower","loop","once","rotation"}){var layer=new PlayerAnimationAccess.Layer();for(int i=0;i<1000;i++)layer.modifiers.add(new Object());PlayerAnimationAccess.data.layers.put(id,layer);}var p=new DummyPlayer();for(int i=0;i<1000;i++)if(!CorpseAnimation38.block(p))throw new AssertionError("dummy not guarded");if(PlayerAnimationAccess.accesses!=1)throw new AssertionError("cleanup must run once, not each render");for(var layer:PlayerAnimationAccess.data.layers.values())if(layer.animation!=null||!layer.modifiers.isEmpty())throw new AssertionError("old fade retained");System.out.println("CORPSE_DUMMY_ANIMATION_CHAINS_CLEARED_ONCE_LIVE_PLAYERS_UNCHANGED=PASS");}}
